cd /workspace/scratch && cat > enc.py <<'EOF'
"""Encoding experiments for the hard link-min query."""
import sys, random, time
sys.path.insert(0,'/workspace/scratch'); sys.path.insert(0,'/workspace/submission')
import gen_big, analyze as A
import z3
from math import lcm

seed = int(sys.argv[1]) if len(sys.argv) > 1 else 3
variant = sys.argv[2] if len(sys.argv) > 2 else 'base'
rng = random.Random(seed)
req = gen_big.build(rng, tight=False)
inst = A._parse_request(req)
edges = inst['edges']; coms = inst['commodities']; snaps = inst['snapshots']
domains = inst['domains']; S=len(snaps); C=len(coms); E=len(edges)
W=[]; coef=[]
for (_cid,_s,_t,routes) in coms:
    row=[0]*E; ws=0
    for p,w in routes:
        ws+=w
        for ei in p: row[ei]+=w
    W.append(ws); coef.append(row)
L=1
for w in W: L=lcm(L,w)
Am=[[coef[c][e]*(L//W[c]) for e in range(E)] for c in range(C)]
q=[[z3.Int('q_%d_%d'%(s,c)) for c in range(C)] for s in range(S)]
n=[[z3.Int('n_%d_%d'%(s,e)) for e in range(E)] for s in range(S)]
base=[]; add=base.append
for s in range(S):
    bnd=snaps[s][1]
    for c in range(C):
        add(q[s][c]>=bnd[c][0]); add(q[s][c]<=bnd[c][1])
    for e in range(E):
        t=[q[s][c]*Am[c][e] for c in range(C) if Am[c][e]]
        add(n[s][e]==(z3.Sum(t) if t else z3.IntVal(0)))
        add(n[s][e]<=L*edges[e][3])
ing={}; egr={}
for i,(_cid,src,tgt,_r) in enumerate(coms):
    ing.setdefault(src,[]).append(i); egr.setdefault(tgt,[]).append(i)
cidx={c[0]:i for i,c in enumerate(coms)}; eidx={e[0]:i for i,e in enumerate(edges)}
violls={}
for s,snap in enumerate(snaps):
    for (_oid,metric,target,lo,hi,dom) in snap[4]:
        if metric=='demand': ex=q[s][cidx[target]]
        elif metric=='link': ex=n[s][eidx[target]]
        else:
            lst=ing.get(target,()) if metric=='ingress' else egr.get(target,())
            ex=z3.Sum([q[s][i] for i in lst]) if lst else z3.IntVal(0)
        sc = L if metric=='link' else 1
        if dom is None:
            add(ex>=lo*sc); add(ex<=hi*sc)
        else:
            violls.setdefault(dom,[]).append((s, z3.Or(ex<lo*sc, ex>hi*sc)))
bmap={}
for d in domains:
    lits=violls.get(d)
    if lits:
        b=z3.Bool('b_'+d)
        if variant=='impl':
            for (s,l) in lits: add(z3.Implies(l, b))
            add(z3.Or([l for (s,l) in lits]) == b)
        else:
            add(b==z3.Or([l for (s,l) in lits]))
        bmap[d]=b
if variant=='perSnap':
    # per-snapshot cardinality: at most k domains violated per snapshot
    cs = {}
    for d in domains:
        for (s, l) in violls.get(d, []):
            cs.setdefault(s, []).append((l, 1))
    for s, items in cs.items():
        add(z3.PbLe(items, inst['max_faults']))
if variant=='ps1':
    cs = {}
    for d in domains:
        for (s, l) in violls.get(d, []):
            cs.setdefault(s, []).append((l, 1))
    for s, items in cs.items():
        add(z3.PbLe(items, inst['max_faults']))
bvars=[bmap[d] for d in domains if d in bmap]
m = z3.Solver(); m.add(*base)
pb=[(b,1) for b in bvars]
m.push(); m.add(z3.PbLe(pb, inst['max_faults'])); r=m.check(); m.pop()
# find k
lo,hi=0,inst['max_faults']
while lo<hi:
    mid=(lo+hi)//2
    m.push(); m.add(z3.PbLe(pb,mid)); ok=m.check()==z3.sat; m.pop()
    if ok: hi=mid
    else: lo=mid+1
k=lo
m.push(); m.add(z3.PbEq(pb,k)); assert m.check()==z3.sat
v0 = m.model()[n[1][3]].as_long()
print('variant=%s k=%d start=%d' % (variant, k, v0), flush=True)
LO = m.nlo if False else sum(A_model.qlo for A_model in [None]) if False else None
# box lower bound for n[1][3]
qlo=[[snap[1][c][0] for c in range(C)] for snap in snaps]
boxlo=sum(qlo[1][c]*Am[c][3] for c in range(C))
print('boxlo', boxlo, flush=True)
lo_b=boxlo; hi=v0
t0=time.time(); nc=0
while lo_b<hi:
    if nc<6: mid=hi-1
    else: mid=(lo_b+hi)//2
    nc+=1
    m.push(); m.add(n[1][3]<=mid); r=m.check(); 
    if r==z3.sat:
        v=m.model()[n[1][3]].as_long(); m.pop(); hi=v
    else:
        m.pop(); lo_b=mid+1
print('min=%d checks=%d time=%.2f' % (lo_b, nc, time.time()-t0), flush=True)
EOF
